// WA Reply: respuesta manual desde el panel de G54 (14-nov). Sigue el contrato de G54 (docs del 5-nov,
// "POST {webhook wa_reply}"): recibe phone, message, company_id y phone_number_id, y solo transporta
// el mensaje a Meta, sin volver a guardarlo en G54 (el panel ya lo guarda). Responde 2xx solo si Meta
// aceptó el envío. Como G54 no manda clave, hay dos candados: la empresa del número de Meta tiene que
// ser la de company_id, y el teléfono tiene que ser un contacto de WhatsApp de esa empresa.
// Reemplaza a wa-reply-g54 (borrado el 14-ago) y a la rama sales-ai-manual, que no calzaban con el contrato.
const B = 'https://apigrowth.mdarthurdigital.com/api';
const AGENT = 'Bearer REDACTED_G54_AGENT_TOKEN';
const b = $input.first().json.body || {};
const fail = (status, motivo, extra = {}) => [{ json: { ok: false, status, motivo, ...extra } }];

const message = String(b.message || '');
const companyId = String(b.company_id ?? '').trim();
const pnid = String(b.phone_number_id ?? '').trim();
const digits = String(b.phone || '').replace(/\D/g, '');
if (!message.trim()) return fail(422, 'Falta message');
if (message.length > 4096) return fail(422, 'message supera los 4096 caracteres que permite WhatsApp');
if (!/^\d+$/.test(companyId)) return fail(422, 'company_id no válido');
if (!/^\d+$/.test(pnid)) return fail(422, 'phone_number_id no válido');
if (digits.length < 8 || digits.length > 15) return fail(422, 'phone no válido');

// G54 espera 12 s en total: cada llamada lleva su propio tope para no pasarse.
const http = (o) => this.helpers.httpRequest({ json: true, timeout: 3500, returnFullResponse: true, ignoreHttpStatusErrors: true,
  ...o, headers: { Accept: 'application/json', 'Content-Type': 'application/json', ...(o.headers || {}) } });

const emp = await http({ url: B + '/agent/wa/empresa-by-phone/' + pnid, headers: { Authorization: AGENT } });
if (emp.statusCode !== 200) return fail(404, 'El número de Meta no está registrado en G54', { g54_status: emp.statusCode });
const e = (emp.body && emp.body.data) || emp.body || {};
if (String(e.company_id) !== companyId) return fail(403, 'El número de Meta no es de esa empresa');
if (!e.wa_access_token) return fail(409, 'La empresa no tiene token de WhatsApp en G54');

const lr = await http({ url: B + '/n8n/companies/' + companyId + '/wa/leads?phone=' + encodeURIComponent('+' + digits) });
const leads = lr.statusCode === 200 && lr.body && Array.isArray(lr.body.data) ? lr.body.data : [];
const lead = leads.find((x) => String(x.phone || '').replace(/\D/g, '') === digits);
if (!lead) return fail(403, 'El teléfono no es un contacto de WhatsApp de esa empresa');

const meta = await http({ method: 'POST', timeout: 5000, url: 'https://graph.facebook.com/v19.0/' + (e.phone_number_id || pnid) + '/messages',
  headers: { Authorization: 'Bearer ' + e.wa_access_token },
  body: { messaging_product: 'whatsapp', to: digits, type: 'text', text: { body: message } } });
const waId = meta.body && meta.body.messages && meta.body.messages[0] && meta.body.messages[0].id;
if (meta.statusCode >= 300 || !waId) {
  const er = (meta.body && meta.body.error) || {};
  return fail(502, 'Meta no aceptó el envío', { meta_status: meta.statusCode, meta_code: er.code, meta_mensaje: er.message || '' });
}
// Para la pausa del bot (siguiente nodo, después de responder a G54).
return [{ json: { ok: true, status: 200, wa_message_id: waId, _pausa: { companyId, digits, datos: lead.datos } } }];

// Pausa al bot en esa conversación (datos_calificacion.bot_pausado, el candado del 14-ago que leen Marco y
// Sales AI). Va después de responder a G54 para no gastar su espera de 12 s. G54 reemplaza datos_calificacion
// entero (comprobado el 14-nov), así que se mandan los datos que ya tenía el lead más la pausa. G54 exige al
// menos un mensaje: va una nota de sistema, no el texto del vendedor (eso lo duplicaría).
const B = 'https://apigrowth.mdarthurdigital.com/api';
const AGENT = 'Bearer REDACTED_G54_AGENT_TOKEN';
const p = $input.first().json._pausa;
const datos = p.datos && typeof p.datos === 'object' && !Array.isArray(p.datos) ? p.datos : {};
try {
  const r = await this.helpers.httpRequest({ method: 'POST', url: B + '/agent/whatsapp/inbound', json: true, timeout: 10000,
    returnFullResponse: true, ignoreHttpStatusErrors: true,
    headers: { Accept: 'application/json', 'Content-Type': 'application/json', Authorization: AGENT },
    body: { empresa_id: Number(p.companyId), phone: '+' + p.digits, canal: 'whatsapp',
      datos_calificacion: { ...datos, bot_pausado: true, motivo: 'Vendedor tomó control manual', fecha: new Date().toISOString() },
      messages: [{ rol: 'sys', contenido: 'El vendedor respondió desde el panel; el bot queda en pausa.' }] } });
  return [{ json: { bot_pausado: r.statusCode < 300, g54_status: r.statusCode } }];
} catch (err) {
  return [{ json: { bot_pausado: false, error: err.message } }];
}
